from adjudication_io import E,read_rows,write_adjudication
import json
r=json.loads((E/'reader_reports/145_scan015_reviewed.json').read_text())
f={x['box']:x['reading'] for x in read_rows(E/'second/145_scan015_first.tsv')}
b={x['box']:[int(x[k]) for k in ['x0','y0','x1','y1']] for x in read_rows(E/'second/145_scan015_boxes.tsv')}
oldstable=r'\unsure{stable}';newstable=r'\unsure{stable|stables}'
c={
'B01':{'final':f['B01'].replace(oldstable,newstable),'changed':True,'adjudication':'Retain the live singular forms, but broaden the crossed old word’s ending.','ink':'The article ends in a small e course, without a separate final hook establishing les. Groupe and envisagé end before the insertion guide, with no distinct plural s. Fixé has the terminal accented e and no following s. The old stable is traversed by a dark strike, including its right end, so an additional s there cannot be excluded. The comma before il is a small separate downward mark at the guide’s return.'},
'B02':{'use_first':True,'adjudication':'Display delimiters only.','ink':'Epsilon0, epsilon1, epsilon-infinity, the equality and1 are all clear. This expression belongs to the broad cancelled block, although the cancellation crosses around rather than through each character.'},
'B04':{'use_first':True,'adjudication':'Retain both local cancellations and the first-factor prime doubt.','ink':'A detached slanted tick lies above/right of the initial l1, so the prime remains uncertain. In the upper first-bracket trial, a dark rising stroke traverses l and the sigma-shaped body independently of the thin page-wide cancellation; that local deletion is real. The lower trial has its own horizontal strike, with both minus-one exponents, l1, l-infinity and sigma0 readable. The second and third substitution labels are likewise legible. The first crossed upper subscript remains doubtful.'},
'B05':{'use_first':True,'adjudication':'Retain OK and the three inverse factors.','ink':'The first letter is the rounded O with angular top entry. The second has an upright and lower rightward diagonal/leg, like the OK on scan013, rather than the rounded arch of a lowercase h. All three minus-one exponents and the order infinity,0,1 are distinct.'},
'B06':{'use_first':True,'adjudication':'Do not add a check mark from a cancellation fragment.','ink':'The short dark tick at left lies on a much longer pale diagonal/curved cancellation stroke that continues out of the crop. It is not an isolated two-stroke check mark. The rectangular frame has four sides and encloses the full epsilon product equality. On a donc and the framed formula remain part of the cancelled block.'},
'B09':{'final':f['B09'].replace('donc aussi',r'donc \unsure{aussi|on a}'),'changed':True,'adjudication':'Retain broad cancellation, but reopen aussi/on a.','ink':'The broad diagonal crosses this prose line and continues toward the displayed sigma product, maintaining its cancelled state. The short course after donc has low joined humps and a separate dark final body, but a crossing stroke obscures part of the middle. Aussi is still possible; segmentation as on a cannot be excluded. The relation inattendue and the indices infinity,1,0 remain clear.'},
'B12':{'use_first':True,'adjudication':'Equivalent graphic serialization.','ink':'There are two separate nearly horizontal strokes, the left short and the right roughly three times longer, separated by a small gap. The existing TikZ drawing preserves their order and relative lengths.'},
'B13':{'use_first':True,'adjudication':'Do not add a colon after notations.','ink':'Two tiny dark spots lie well below the end of notations, rather than at the text’s punctuation height or between the words. The following et de l’approche begins normally. These isolated lower spots do not establish a written colon. The existing full stop after approche is clear.'},
'B14':{'use_first':True,'adjudication':'Retain the visible singular adjective profini.','ink':'The word ends with a short vertical i and its dot. Clear blank paper separates it from the following dash; no s is written. The preceding discrets has its own terminal s and comma. The agreement break is preserved without grammatical repair.'},
'B15':{'final':f['B15'].replace('(et',r'\unsure{(et|Cat}'),'changed':True,'adjudication':'Reopen the small parenthetical/letter sequence; retain barred m.','ink':'After the crossed utiliser is a large open left curve followed by a low loop and tall terminal stroke. These can be an opening parenthesis plus e/t, or C/a/t. There is no secure triangular A beginning for Aut, nor a closed O that establishes Out. The next sign has one straight upper bar and a separate wavy two-humped lower body, supporting barred m rather than two straight equality bars or an upper tilde. The following pour les is clear.'}}
for x in r['changes']:
 if x['id'] in ['s015-02','s015-03']:x.update(final=x['final'].replace(oldstable,newstable),ink=c['B01']['ink'],crop='crops/second_145_scan015_B01.png',box=b['B01'])
 if x['id']=='s015-21':x.update(final=r'\unsure{(et|Cat} $\bar m$',ink=c['B15']['ink'],confidence='medium',crop='crops/second_145_scan015_B15.png',box=b['B15'])
for x in r['doubts']:
 if x['reading']==r'\deleted{\unsure{stable}}':x.update(reading=r'\deleted{'+newstable+'}',alternatives=['stable','stables'],reason=c['B01']['ink'])
r['doubts'].extend([
 {'place':'cancelled prose before unexpected sigma relation','reading':r'\unsure{aussi|on a}','alternatives':['aussi','on a'],'confidence':'low','reason':c['B09']['ink']},
 {'place':'final line after cancelled utiliser','reading':r'\unsure{(et|Cat}','alternatives':['(et','Cat'],'confidence':'low','reason':c['B15']['ink']}])
for x in r['inventory']:
 x['first_words_or_objects']=x['first_words_or_objects'].replace(oldstable,newstable).replace('donc aussi',r'donc \unsure{aussi|on a}').replace('(et',r'\unsure{(et|Cat}')
r['notes']=[x.replace('The last parenthesis remains unclosed at the page end.','The preferred final reading has an unclosed parenthesis; the blind audit retains Cat as an alternative to (et.') for x in r['notes']]
r['notes'].append('The blind audit retains the broad upper cancellation and the two local first-bracket cancellations after separating them from the page-wide strokes. A small tick beside the framed formula belongs to a longer cancellation and is not added as a check mark; tiny spots below notations do not establish a colon. The crossed stable/stables ending, aussi/on a and final (et/Cat remain qualified. The live singular profini and discret are preserved. These changes of certainty do not add new mathematical checks.')
r['hand'].append('Blind audit: one low loop plus a tall terminal after an open curve can be (et or Cat, so the whole cluster must be qualified separately from the clearly barred-m abbreviation beside it. An isolated tick on a long cancellation is not an independent check mark; a pair of dark spots below the text line is not automatically a colon. Final i-plus-dot in profini has no additional s.')
edits=[{'old':oldstable,'new':newstable},{'old':'donc aussi la relation inattendue','new':r'donc \unsure{aussi|on a} la relation inattendue'},{'old':r'(et $\bar m$','new':r'\unsure{(et|Cat} $\bar m$'}]
write_adjudication(15,'/root/reader_b',c,edits,report_replace={k:r[k] for k in ['changes','doubts','inventory','notes','hand']})
